import React, { useState, useEffect } from 'react';
import { Button } from '../ui/button';
import { Textarea } from '../ui/textarea';
import { Avatar, AvatarFallback } from '../ui/avatar';
import { Trash2, Edit2 } from 'lucide-react';
import { commentService } from '../../services/commentService';
import { useAuth } from '../../contexts/AuthContext';
import { formatDate } from '../../utils/formatters';

export const CommentSection = ({ projectId, taskId = null }) => {
  const { user } = useAuth();
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [editContent, setEditContent] = useState('');

  useEffect(() => {
    loadComments();
  }, [projectId]);

  const loadComments = async () => {
    try {
      const data = await commentService.getByProject(projectId);
      const filtered = taskId 
        ? data.filter(c => c.task_id === taskId)
        : data.filter(c => !c.task_id);
      setComments(filtered);
    } catch (error) {
      console.error('Error loading comments:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    setLoading(true);
    try {
      await commentService.create({
        content: newComment,
        project_id: projectId,
        task_id: taskId,
      });
      setNewComment('');
      await loadComments();
    } catch (error) {
      alert('Error al crear comentario');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = async (commentId) => {
    setLoading(true);
    try {
      await commentService.update(commentId, editContent);
      setEditingId(null);
      await loadComments();
    } catch (error) {
      alert('Error al actualizar comentario');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (commentId) => {
    if (!window.confirm('¿Eliminar comentario?')) return;

    try {
      await commentService.delete(commentId);
      await loadComments();
    } catch (error) {
      alert('Error al eliminar comentario');
    }
  };

  return (
    <div className="space-y-4">
      {/* Formulario nuevo comentario */}
      <form onSubmit={handleSubmit} className="space-y-2">
        <Textarea
          value={newComment}
          onChange={(e) => setNewComment(e.target.value)}
          placeholder="Escribe un comentario..."
          rows={3}
        />
        <Button 
          type="submit" 
          disabled={loading || !newComment.trim()}
          className="bg-green-600 hover:bg-green-700"
        >
          {loading ? 'Enviando...' : 'Comentar'}
        </Button>
      </form>

      {/* Lista de comentarios */}
      <div className="space-y-3">
        {comments.map((comment) => (
          <div key={comment._id} className="bg-gray-50 rounded-lg p-4">
            <div className="flex items-start justify-between">
              <div className="flex items-start gap-3 flex-1">
                <Avatar className="h-8 w-8">
                  <AvatarFallback className="text-xs">
                    {comment.user_id.full_name?.charAt(0)}
                  </AvatarFallback>
                </Avatar>
                
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-semibold text-sm">
                      {comment.user_id.full_name}
                    </span>
                    <span className="text-xs text-gray-500">
                      {formatDate(comment.created_at)}
                    </span>
                  </div>
                  
                  {editingId === comment._id ? (
                    <div className="space-y-2">
                      <Textarea
                        value={editContent}
                        onChange={(e) => setEditContent(e.target.value)}
                        rows={2}
                      />
                      <div className="flex gap-2">
                        <Button 
                          size="sm" 
                          onClick={() => handleEdit(comment._id)}
                        >
                          Guardar
                        </Button>
                        <Button 
                          size="sm" 
                          variant="outline"
                          onClick={() => setEditingId(null)}
                        >
                          Cancelar
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <p className="text-sm text-gray-700">{comment.content}</p>
                  )}
                </div>
              </div>

              {/* Acciones (solo autor) */}
              {comment.user_id._id === user._id && editingId !== comment._id && (
                <div className="flex gap-1">
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => {
                      setEditingId(comment._id);
                      setEditContent(comment.content);
                    }}
                  >
                    <Edit2 className="w-4 h-4" />
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleDelete(comment._id)}
                    className="text-red-600 hover:text-red-700"
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              )}
            </div>
          </div>
        ))}

        {comments.length === 0 && (
          <p className="text-center text-gray-500 py-8">
            No hay comentarios aún
          </p>
        )}
      </div>
    </div>
  );
};
